///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/formProcess.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50206.tx_fn_Excel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_List_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_Delete_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ExcelReq').set('pageIndex', 1);
    await scwin.list();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/formProcess.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "findFormProcesses");
    await scwin.tx_fn_List_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent('listDiv') && $c.util.getComponent('listDiv').setValue) ? $c.util.getComponent('listDiv').setValue(responseText) : (($c.util.getComponent('listDiv') && $c.util.getComponent('listDiv').setText) ? $c.util.getComponent('listDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'listDiv'), void (responseText)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.popInsert = async function () {
    /* sdd-asis-lifecycle:begin fn_PopInsert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/formProcess.do?method=prepareUpdateFormProcess&mode=create";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "formProcessPop", popupName: "formProcessPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popModify
 * @author Inswave
 * @date 2026. 09. 29
 * @param formProcsCd
 * @returns
 * @hidden N
*/
scwin.popModify = async function (formProcsCd) {
    /* sdd-asis-lifecycle:begin fn_PopModify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/formProcess.do?method=prepareUpdateFormProcess&formProcsCd=" + formProcsCd + "&mode=update";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "formProcessPop", popupName: "formProcessPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteExcelReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param formProcsCd formProcsNm
 * @returns
 * @hidden N
*/
scwin.deleteExcelReq = async function (formProcsCd, formProcsNm) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("서식처리절차 '" + formProcsNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ExcelReq').set('formProcsCd', formProcsCd);
    scwin.form_listForm.action = "/filing/formProcess.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "deleteFormProcess");
    await scwin.tx_fn_Delete_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excel = async function () {
    /* sdd-asis-lifecycle:begin fn_Excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/formProcess.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "downloadFormProcessList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
    /* sdd-asis-lifecycle:end */
};
